sys_script_fix.script:
var eventGR = new GlideRecord('x_1790229_event_ma_event_record');
eventGR.addQuery('number', 'EVT0001017');
eventGR.query();

if (eventGR.next()) {
    var scheduleGR = new GlideRecord('x_1790229_event_ma_schedule');
    scheduleGR.addQuery('u_event_id', eventGR.getUniqueValue());
    scheduleGR.query();

    while (scheduleGR.next()) {
        gs.info('Activity: ' + scheduleGR.getValue('u_activity_name'));
        gs.info('Start Time: ' + scheduleGR.getDisplayValue('u_start_date'));
        gs.info('End Time: ' + scheduleGR.getDisplayValue('u_end_date'));
        gs.info('Location: ' + scheduleGR.getValue('u_location'));
    }
} else {
    gs.info('Event not found with number EVT0001017');
}
